import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  Future<void>? _currencyListFuture;

  List<CurrencyModel> _allCurrencies = [];

  bool _isLoadingMore = false;

  int _currentPage = 0;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _initAnimation();
    _refreshData();
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed && _currencyListFuture != null) {
      // При возврате на экран обновляем данные с первой страницы и базовой валютой по умолчанию
      _refreshData();
    } else if (state == AppLifecycleState.paused || state == AppLifecycleState.inactive) {
      // Сбрасываем флаг загрузки при потере фокуса, чтобы не висел индикатор
      setState(() => _isLoadingMore = false);
    }
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: Duration(milliseconds: 400),
      vsync: this,
    );
  }

  Future<void> _refreshData() async {
    setState(() {
      _currentPage = 0;
      _allCurrencies = [];
      _isLoadingMore = false;
    });
    await _loadPage(0);
  }

  Future<void> _loadPage(int page) async {
    final currencyRepository = context.read<CurrencyRepository>();

    if (page == 0) {
      setState(() => _currencyListFuture = null);
      final List<CurrencyModel> value = await currencyRepository.fetchRates(const CurrencyPageRequest()).then((CurrencyPage currencyPage) {
        final List<CurrencyModel> items = currencyPage.items;
        return items;
      });

      if (!mounted) return;

      setState(() {
        _allCurrencies = value;
        _filteredCurrenciesNotifier = ValueNotifier(value);
        _currentPage = 1;
      });

      _fadeController.forward();

      currencyRepository.saveCurrencyList(value);
    } else {
      final CurrencyPage nextPage = await currencyRepository.fetchRates(CurrencyPageRequest(page: page));

      if (!mounted) return;

      setState(() {
        _isLoadingMore = true;
      });

      setState(() {
        _allCurrencies.addAll(nextPage.items);
        _filteredCurrenciesNotifier.value = List.from(_allCurrencies, growable: false);
        _currentPage = nextPage.hasMore ? page + 1 : _currentPage;
        _isLoadingMore = false;
      });
    }

